(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
  const width = process.env.WIDTH ? Number(process.env.WIDTH) : null;
  const height = process.env.HEIGHT ? Number(process.env.HEIGHT) : null;
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
  globalThis.width = width;
  globalThis.height = height;
})();

(async () => {
  const sharpMod = await import('sharp');
  const sharp = sharpMod.default || sharpMod;
  if (typeof sharp !== 'function') throw new Error('sharp export not a function');
  const input = globalThis.inputPath;
  const output = globalThis.outputPath;
  const resizeOpts = {};
  if (globalThis.width) resizeOpts.width = globalThis.width;
  if (globalThis.height) resizeOpts.height = globalThis.height;
  await sharp(input).resize(resizeOpts).toFile(output);
})();
